#!/usr/bin/env bash
# shellcheck disable=SC1091
# Tvijo Code branding, applied on top of VSCodium's own renaming.
#
# Called from prepare_vscode.sh (the only upstream file we touch) while the
# working directory is ./vscode. Everything Tvijo-specific lives under tvijo/,
# so merging a new VSCodium tag is one hook line to keep, not a rebrand.

set -e

TVIJO_DIR="../tvijo"

. ../utils.sh

# Images: generated by tvijo/make_icons.py, same layout as src/stable.
cp -rp "${TVIJO_DIR}/src/stable/." .

# Identity: VSCodium hardcodes its names in prepare_vscode.sh, ours win the merge.
jsonTmp=$( jq -s '.[0] as $base | .[1] as $brand | $base * $brand | .builtInExtensionsEnabledWithAutoUpdates = (($base.builtInExtensionsEnabledWithAutoUpdates // []) + ($brand.builtInExtensionsEnabledWithAutoUpdates // []) | unique)' product.json "${TVIJO_DIR}/product.json" )
echo "${jsonTmp}" > product.json && unset jsonTmp

replace 's|"VSCodium"|"Tvijo"|' package.json
replace 's|VSCodium|Tvijo|g' build/lib/electron.ts

jsonTmp=$( jq '.name = "Tvijo Code" | .short_name = "Tvijo Code"' resources/server/manifest.json )
echo "${jsonTmp}" > resources/server/manifest.json && unset jsonTmp

replace 's|ShortDisplayName="[^"]*"|ShortDisplayName="Tvijo Code"|' resources/win32/VisualElementsManifest.xml

for file in resources/linux/code.desktop resources/linux/code-url-handler.desktop; do
  replace 's|^Keywords=.*|Keywords=tvijo;tvijocode;code;editor;|' "${file}"
done

if [[ "${OS_NAME}" == "linux" ]]; then
  for file in resources/linux/code.appdata.xml resources/linux/debian/control.template resources/linux/rpm/code.spec.template; do
    replace 's|VSCodium Team https://github.com/VSCodium/vscodium/graphs/contributors|Tvijo https://github.com/nikbibamon/tvijocode|g' "${file}"
    replace 's|https://github.com/VSCodium/vscodium#download-install|https://github.com/nikbibamon/tvijocode/releases|g' "${file}"
    replace 's|https://vscodium.com/img/vscodium.png|https://raw.githubusercontent.com/nikbibamon/tvijocode/main/tvijo/src/stable/resources/linux/code.png|g' "${file}"
    replace 's|https://vscodium.com|https://tvijo.com|g' "${file}"
    replace 's|VSCodium Team|Tvijo|g' "${file}"
    replace 's|VSCodium|Tvijo Code|g' "${file}"
  done

  replace 's|codium|tvijocode|' resources/linux/debian/postinst.template
elif [[ "${OS_NAME}" == "windows" ]]; then
  replace 's|https://vscodium.com|https://tvijo.com|g' build/win32/code.iss
  replace 's|VSCodium|Tvijo|g' build/win32/code.iss
fi

echo "Tvijo branding applied: $( jq -r '.nameLong + " / " + .applicationName' product.json )"
